), reel_f AS (
  SELECT p.proname||'('||pg_get_function_identity_arguments(p.oid)||')' signature, left(md5(pg_get_functiondef(p.oid)),8) empreinte
  FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.prokind = 'f'
), attendu_t(table_name) AS (VALUES ('agent_audit_events'),('agent_conversations'),('agent_document_chunks'),('agent_documents'),('agent_messages'),('agent_versions'),('agents'),('api_rate_limits'),('booking_availability_rules'),('booking_calendar_connections'),('booking_exceptions'),('booking_practitioners'),('booking_request_intake_events'),('booking_requests'),('booking_services'),('booking_slot_offers'),('bookings'),('chronosphere_credit_packs'),('chronosphere_pack_draws'),('chronosphere_paid_draws'),('chronosphere_timeline_entries'),('chronosphere_timelines'),('conference_admins'),('conference_events'),('conference_pass_events'),('conference_passes'),('conference_questions'),('conference_raffle_entries'),('conference_raffles'),('conference_registrations'),('conference_rehearsal_tokens'),('customer_reviews'),('defi_reminders'),('geocoding_cache'),('geocoding_rate_limit'),('gift_card_delivery_secrets'),('gift_card_redemptions'),('gift_cards'),('kdp_income_reports'),('lumia_action_attempts'),('lumia_action_intents'),('lumia_calendar_sync_jobs'),('lumia_message_inbox'),('mediumia_access_codes_v2'),('mediumia_customer_consents'),('mediumia_customers'),('mediumia_email_question_paypal_events'),('mediumia_email_questions'),('mediumia_entitlements'),('mediumia_event_daily_counts'),('mediumia_formation_payments'),('mediumia_formation_subscriptions'),('mediumia_formation_unlock_orders'),('mediumia_paypal_order_intents'),('mediumia_paypal_plans'),('mediumia_paypal_purchases'),('mediumia_profiles'),('mediumia_student_state'),('mediumia_students'),('mediumia_valid_codes'),('oauth_states'),('oracle_email_sequence_subscriptions'),('oracle_free_draws'),('oracle_rate_limits'),('oracle_timeline_cards'),('oracle_timeline_follow_plans'),('pro_audit_events'),('pro_document_agent_access'),('pro_document_chunks'),('pro_document_storage_jobs'),('pro_document_sync_queue'),('pro_document_versions'),('pro_documents'),('pro_invitations'),('pro_memberships'),('pro_public_assistant_usage'),('pro_usage_counters'),('pro_waitlist'),('pro_workspace_members'),('pro_workspaces'),('rdv_balance_owner_alerts'),('rdv_balance_payments'),('rdv_balance_restorations'),('rdv_balance_review_events'),('rdv_balance_runtime_settings'),('rdv_balance_sweep_tokens'),('rdv_booking_action_history'),('rdv_booking_holds'),('rdv_booking_no_show_events'),('rdv_calendar_sync_jobs'),('rdv_checkout_events'),('rdv_deposit_transfers'),('rdv_financial_entries'),('rdv_payment_refunds'),('rdv_payment_settlement_events'),('rdv_paypal_payments'),('reseau_applications'))
SELECT 'fonction_manquante' AS ecart, a.signature AS objet FROM attendu_f a LEFT JOIN reel_f r USING (signature) WHERE r.signature IS NULL
UNION ALL
SELECT 'fonction_differente', a.signature FROM attendu_f a JOIN reel_f r USING (signature) WHERE r.empreinte <> a.empreinte
UNION ALL
SELECT 'table_manquante', t.table_name FROM attendu_t t WHERE to_regclass('public.'||t.table_name) IS NULL
ORDER BY 1, 2;
